// Motivations are game scores. Daily decisions do not imply human verbal thought.
const clamp=n=>Math.max(0,Math.min(100,n));
export function memoryBias(s,target){return Math.max(-15,Math.min(15,(s.episodes||[]).filter(m=>m.target===target).reduce((v,m)=>v+m.valence*m.intensity*Math.exp(-(s.day-m.day)/m.persistence)*.08,0)))}
export const ACTION_MOTIVES={social:['greet','approach','hand','near','person','enter','seek','visit','parallel','quiet'],explore:['roll','search','nose','step','explore','tug','carry','pull','field','curve','detour'],rest:['rest','wait','watch','lie','short','sit','still','den'],avoid:['retreat','back','leave','away','space','pass','separate'],food:['eat','known','lick','bowl','food'],water:['drink','water']};
export function motives(s){const t=s.worldModel.traits,n=s.needs;return {food:n.hunger,water:n.thirst,rest:clamp(n.fatigue+(s.medical?.episode?35:0)+(s.clinical?.active?20:0)),avoid:clamp(s.stress*.7+t.sensitivity*.3),social:clamp(t.sociability*.7+(100-s.familyBond)*.15-s.stress*.2),explore:clamp(t.curiosity*.45+t.energy*.35+(t.independence??50)*.2-n.fatigue*.3)}}
export function behaviorWeight(s,option){const t=s.worldModel.traits,id=option.id,m=motives(s),type=Object.keys(ACTION_MOTIVES).find(k=>ACTION_MOTIVES[k].includes(id));let w=1+(type?m[type]/40:0);const target=s.pending?.context?.actor|| (s.pending?.id==='dog-meet'?s.friend.id:s.pending?.id==='pain-response'?'veterinary-care':s.pending?.id==='encounter'?'visitor':s.caregiverId||'caregiver');const history=memoryBias(s,target);if(type==='social')w+=(t.sociability+s.trust)/150+history/12-(t.independence??50)/180;if(type==='avoid')w-=history/20;if(type==='explore')w+=(t.independence??50)/70;if(['social','explore'].includes(type)&&s.lastAreaChange&&s.day-s.lastAreaChange.day<21)w*=.25+(t.adaptability??50)/120;if(s.clinical?.mobility<80&&type==='explore')w*=s.clinical.mobility/100;return Math.max(.1,w)}
export function dailyBehavior(s){const m=motives(s);s.behavior??={version:1,goal:'rest',activity:.5,history:[]};const ranked=Object.entries(m).sort((a,b)=>b[1]-a[1]);s.behavior.goal=ranked[0][0];s.behavior.motives=m;const sick=!!s.medical?.episode||['recovery','rehabilitation'].includes(s.clinical?.active?.stage);s.behavior.activity=sick?.2:Math.max(.2,Math.min(1.5,(s.worldModel.traits.energy/100+.35)*(s.behavior.goal==='rest'?.4:s.behavior.goal==='explore'?1.2:.8)));if(s.day%30===0){s.behavior.history.push({day:s.day,goal:s.behavior.goal});s.behavior.history=s.behavior.history.slice(-24)}return s.behavior;}
export function learnAction(s,p,id){const t=s.worldModel.traits,type=Object.keys(ACTION_MOTIVES).find(k=>ACTION_MOTIVES[k].includes(id));if(type==='explore')t.independence=clamp((t.independence??50)+.3);if(type==='social')t.sociability=clamp(t.sociability+.2);if(s.lastAreaChange&&s.day-s.lastAreaChange.day<30&&['social','explore','rest'].includes(type))t.adaptability=clamp((t.adaptability??50)+.4);}
